=<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Exhibition Feedback</title>
<style>
  body { font-family: Arial, sans-serif; text-align: center; padding: 50px; background: #f5f5f5; }
  .container { background: #fff; padding: 20px; border-radius: 10px; max-width: 400px; margin: auto; box-shadow: 0 0 10px rgba(0,0,0,0.1); }
  button { padding: 10px 20px; margin-top: 20px; cursor: pointer; }
  #responseMsg { margin-top: 20px; font-weight: bold; color: green; }
</style>
</head>
<body>

<div class="container">
  <h2>Exhibition Feedback</h2>

  <form id="feedbackForm">
    <input type="text" name="name" placeholder="Name / नाम" required><br><br>
    <input type="text" name="mobile" placeholder="Mobile / मोबाइल" required><br><br>
    <button type="submit">Submit / जमा करें</button>
  </form>

  <div id="responseMsg"></div>
</div>

<script>
document.getElementById('feedbackForm').addEventListener('submit', async function(e) {
  e.preventDefault();
  const form = e.target;
  const data = {
    name: form.name.value,
    mobile: form.mobile.value,
    timestamp: new Date().toISOString()
  };

  try {
    const response = await fetch('https://vinodnic.app.n8n.cloud/webhook/Exhibition', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data)
    });
    const result = await response.json();
    document.getElementById('responseMsg').innerText = result.message || "Feedback submitted successfully! / फीडबैक सफलतापूर्वक जमा।";
    form.reset();
  } catch (err) {
    document.getElementById('responseMsg').innerText = "Error submitting feedback. / प्रतिक्रिया जमा करने में त्रुटि।";
  }
});
</script>

</body>
</html>

